// Kota kontrolu (19 Eyl 2026). Bu akista daha once HIC limit yoktu: webhook
// kimlik dogrulamasiz oldugu icin adresini bilen herkes sinirsiz cagirabiliyordu.
// Kota kullanici bazli: backend gercek kimligi govdede 'kkbKimlik' olarak
// yolluyor. WordPress'ten gelen giris yapmamis isteklerde bu alan olmaz, o
// zaman IP'ye duseriz. IP tek basina guvenilir degil (mobil veride degisir,
// ortak wifi'de birlesir), bu yuzden kimlik varsa o tercih edilir.
//
// ONEMLI: cikti girdinin AYNISI olmali, uzerine yalnizca bayrak eklenir.
// Alan beyaz listesi yapilirsa asagidaki dugumler body'yi bulamaz -- ayni
// hata 11 Eyl 2026'da 'Plan Yaniti'nda replik alanini dusurmustu.
const girdi = $input.first().json;
const kimlikGovde = girdi.body || girdi;
const ip = kimlikGovde.kkbKimlik || girdi.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || girdi.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const key = 'rl_viral_' + ip + '_' + today;
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};
// 7 gunden eski sayaclari sil, yoksa static data sinirsiz buyur.
const silSiniri = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
for (const k of Object.keys(staticData.rateLimits)) {
  const kTarih = k.slice(-10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(kTarih) && kTarih < silSiniri) delete staticData.rateLimits[k];
}
const current = staticData.rateLimits[key] || 0;
if (current >= 50) {
  return [{ json: { ...girdi, rateLimitExceeded: true } }];
}
staticData.rateLimits[key] = current + 1;
return [{ json: { ...girdi, rateLimitExceeded: false } }];

/**
 * KOTA YANITI -- gunluk sinir dolunca doner.
 *
 * Bu akis responseMode='lastNode' kullaniyor; HTTP 429 dondurmek icin butun
 * basari yollarina ayrica 'Respond to Webhook' dugumu eklemek gerekirdi.
 * Onun yerine akisin kendi hata kalibina uyuyoruz -- frontend zaten `error`
 * alanini kullaniciya gosteriyor.
 */
return [{ json: {
  // Backend bu isareti gorunce 429 dondurur; aylik hak ve kredi HARCANMAZ.
  _kotaDoldu: true,
  error: 'Günlük kullanım sınırına ulaştınız. Yarın tekrar deneyebilirsiniz.',
} }];

const body = $('Webhook').first().json.body || $('Webhook').first().json;
const videoUrl = body.videoUrl || body.video_url || '';
const videoDesc = body.videoDesc || body.video_desc || body.prompt || '';
const sector = body.sector || 'Genel';
const biz = body.biz || '';
const tones = Array.isArray(body.tones) ? body.tones.join(' + ') : (body.tones || 'Eğlendirici');
const note = body.note || '';

// Firma web sitesi scrape sonucu (varsa)
let firmaBilgisi = '';
try {
  const scraped = $('Firma Scrape').first().json?.data || $('Firma Scrape').first().json?.body || '';
  firmaBilgisi = String(scraped).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1500);
} catch(e) { firmaBilgisi = ''; }

if (!videoDesc || videoDesc.length < 10) {
  return [{ json: { error: 'Geçersiz istek: video açıklaması eksik.' } }];
}

const systemMessage = `Sen bir içerik stratejisti ve format mining uzmanısın.
Görevin: Kullanıcının tarif ettiği viral videonun arkasındaki tekrarlanabilir FORMAT yapısını çıkarmak ve farklı sektörlere uyarlamak.

Temel kavramlar:
- FORMAT: Videonun kendisi değil, kurgu mantığı — hook + yapı + CTA kalıbı
- FORMAT MİNİNG: Başarılı videodan soyut, tekrar kullanılabilir içerik şablonu çıkarmak
- FORMAT REPLİKASYON: Aynı kurgu yapısını farklı sektör/marka için uyarlamak

Çıktı her zaman geçerli JSON olmalıdır. Markdown kullanma. Sadece JSON döndür. Düşünme sürecini kısa tut.`;

const userPrompt = `Viral video bilgisi:
${videoUrl ? 'Link: ' + videoUrl : ''}
Açıklama: ${videoDesc}
${note ? 'Ek not: ' + note : ''}${firmaBilgisi ? '\nFirma web sitesinden elde edilen bilgi:\n' + firmaBilgisi : ''}

Görev:
1. Bu videonun FORMAT yapısını çıkar (hook + kurgu + CTA mantığı)
2. Formatı 3 farklı sektöre uyarla — birincisi mutlaka "${sector}" sektörü olsun
3. Her sektör için: hook cümlesi + sahne sahne senaryo taslağı yaz

İşletme: ${biz || 'belirtilmemiş'}
Ton: ${tones}

ZORUNLU JSON ÇIKTI ŞEMASI (sadece bunu döndür):
{
  "format_adi": "Videonun format adı (kısa, tanımlayıcı)",
  "format_tipi": "POV | Mini skeç | Reveal | Before/After | Us vs Them | Text overlay | Micro-drama | Diğer",
  "format_aciklamasi": "Formatın kurgu mantığı — hook + yapı + CTA",
  "kurgu_yapisi": "Sahne 1 (X sn): ... → Sahne 2 (X sn): ... → Sahne 3 (X sn): ...",
  "sure": "tahmini süre",
  "ornek_hook": "İlk 1-3 saniyede söylenecek cümle",
  "uretim_zorlugu": "Çok Düşük | Düşük | Orta | Yüksek",
  "marka_guvenligi": "Yüksek | Orta | Dikkat Gerekir",
  "sektore_ozgu_uyarlamalar": [
    {
      "sektor": "${sector}",
      "hook": "Bu sektöre özel hook cümlesi",
      "senaryo_taslagi": "Sahne sahne kısa senaryo (3-5 cümle)",
      "cta": "Harekete geçirme cümlesi"
    },
    {
      "sektor": "2. sektör adı",
      "hook": "...",
      "senaryo_taslagi": "...",
      "cta": "..."
    },
    {
      "sektor": "3. sektör adı",
      "hook": "...",
      "senaryo_taslagi": "...",
      "cta": "..."
    }
  ],
  "uygulama_ipuclari": "Bu formatı uygularken dikkat edilmesi gereken 2-3 pratik ipucu"
}`;

const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 8000,
  messages: [
    { role: 'system', content: systemMessage },
    { role: 'user', content: userPrompt }
  ]
};
return [{ json: { ...body, apiBody, apiBodyStr: JSON.stringify(apiBody) } }];

const apiData = $input.first().json;
const msg = apiData.choices?.[0]?.message || {};
let text = msg.content || msg.reasoning_content || '';

// MiniMax-M3 reasoning (<think>) blogu: icindeki suslu parantezler JSON
// cikarimini bozuyordu (canlida tespit edildi) - blogu tamamen at.
const thinkEnd = text.lastIndexOf('</think>');
if (thinkEnd !== -1) text = text.slice(thinkEnd + '</think>'.length);

// ```json ... ``` sarmalayicisini kaldir
text = text.replace(/```(?:json)?/gi, '');

// JSON bloğunu çıkar
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);

// TR_RESTORE — MiniMax GBK encoding fix
const TR_RESTORE = {
  '\u7709': 'ü', '\u8267': 'ş', '\u679a': 'ö', '\u83bd': 'ç',
  '\u8c0b': 'ı', '\u81d2': 'ğ', '\u811f': 'Ç', '\u813a': 'Ü',
  '\u8266': 'Ş', '\u8130': 'Ö', '\u81d1': 'Ğ', '\u964c': 'İ',
};
const TR_KEYS = Object.keys(TR_RESTORE).join('');
const TR_RE = new RegExp('[' + TR_KEYS + ']', 'g');
text = text.replace(TR_RE, ch => TR_RESTORE[ch] || ch);

function tryParseJson(raw) {
  try { return { ok: true, value: JSON.parse(raw) }; }
  catch (e1) {
    const repaired = raw
      .replace(/,\s*([\]}])/g, '$1')
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
    try { return { ok: true, value: JSON.parse(repaired) }; }
    catch (e2) { return { ok: false, error: e1.message }; }
  }
}

const parsed = tryParseJson(text);
if (!parsed.ok) {
  return [{ json: {
    _parseError: true,
    _rawText: text.slice(0, 500),
    error: 'AI çıktısı geçerli JSON değildi: ' + parsed.error
  }}];
}

const result = parsed.value;
return [{ json: { ...result, _ok: true } }];

const err = $input.first().json;
const msg = err?.error?.message || err?.message || JSON.stringify(err).slice(0, 200);
return [{ json: { error: 'MiniMax API hatası: ' + msg } }];
